CREATE TABLE jfy_gift (
    id                      NUMBER(10)     NOT NULL,
    gift_name               VARCHAR2(32)   NOT NULL,
    at_least_recharge_count NUMBER(10)     DEFAULT 1 NOT NULL,
    comments                CLOB           NOT NULL,
    content                 CLOB           NOT NULL,
    cost_price              NUMBER(10, 2)  DEFAULT NULL,
    cover                   VARCHAR2(255),
    covers                  CLOB           NOT NULL,
    description             VARCHAR2(62),
    express_type            CLOB           NOT NULL,
    gift_type               NUMBER(10)     NOT NULL,
    has_props               NUMBER(1)      DEFAULT 0 NOT NULL,
    is_limit_sell           NUMBER(3)      DEFAULT 0 NOT NULL,
    limit_customer_tags     CLOB           NOT NULL,
    limit_sell_custom       NUMBER(3)      DEFAULT 0 NOT NULL,
    limit_sell_cycle        VARCHAR2(32),
    limit_sell_cycle_count  NUMBER(10)     NOT NULL,
    limit_sell_type         NUMBER(3)      NOT NULL,
    market_price            NUMBER(10, 2)  NOT NULL,
    out_sn                  VARCHAR2(255)  NOT NULL,
    props                   CLOB           NOT NULL,
    skus                    CLOB           NOT NULL,
    score_price             NUMBER(10, 2)  NOT NULL,
    stock                   NUMBER(10)     NOT NULL,
    create_at               TIMESTAMP      NOT NULL,
    store_id                NUMBER(10)     NOT NULL,
    status                  NUMBER(10)     DEFAULT 1,
    view_count              NUMBER(10)     DEFAULT 0 NOT NULL,
    sell_count              NUMBER(10)     DEFAULT 0,
    PRIMARY KEY (id)
);
